from common import *
import shutil,yaml

def layout(cfg):
 s=cfg['scene'];m=s['objects']['movable_objects'];return {'scene':s.get('_target_'),'drawer':s['objects']['fixed_objects']['table']['joints']['base__drawer']['initial_state'],'blocks':{c:{k:m['block_'+c][k] for k in ['initial_pos','initial_orn']}for c in ['red','blue','pink']}}

def main():
 assert not E.exists(),E
 for x in ['configs','source','data/public','data/annotation_private','results','logs','models']: (E/x).mkdir(parents=True,exist_ok=True)
 R.mkdir(parents=True)
 old=[]
 for p in (P/'experiments').rglob('resolved_config.yaml'):
  if p.is_relative_to(E):continue
  try: old.append({'path':str(p),'sha256':sha(p),'layout':layout(yaml.safe_load(p.read_text()))})
  except (KeyError,TypeError,yaml.YAMLError):pass
 roots=[]
 for scene in 'ABCD':
  for k in range(8):
   seed=261018200+100*'ABCD'.index(scene)+k;rng=np.random.default_rng(seed);colors=rng.permutation(['red','blue','pink']);blocks={}
   for color,x in zip(colors,[-.15,.075,.30]):blocks[str(color)]={'initial_pos':[float(x+rng.uniform(-.015,.015)),float(rng.uniform(-.115,-.045)),.46],'initial_orn':[0.,0.,float(rng.uniform(-.35,.35))]}
   drawer=float(np.clip([.005,.065,.15,.235][k//2]+rng.uniform(-.004,.004),0,.275));wps=[]
   # Reproducible motor commands: fixed counts, no reach/success selection.
   bases=[[-.10,-.22,.60],[.16,-.22,.60],[.04,-.16,.53],[-.14,-.26,.67],[.20,-.13,.66],[.02,-.29,.56],[.03,-.22,.60]]
   for j,base in enumerate(bases):
    wps.append({'xyz':(np.array(base)+rng.uniform([-.025,-.018,-.018],[.025,.018,.018])).tolist(),'euler':[float(3.09+rng.uniform(-.12,.12)),float(rng.uniform(-.18,.18)),float(1.5+rng.uniform(-.45,.45))],'grip':1 if j%2==0 else -1,'control_periods':24,'physics_ticks_per_period':8})
   root={'root_id':f'sync256_{scene}_{k:02d}','scene':scene,'split':'train'if scene in 'AB'else('dev'if scene=='C'else'final'),'seed':seed,'drawer_initial_q_m':drawer,'blocks':blocks,'waypoints':wps}
   root['initialization_signature']=hashlib.sha256(json.dumps({'scene':scene,'drawer':drawer,'blocks':blocks},sort_keys=True).encode()).hexdigest();roots.append(root)
 assert len({r['initialization_signature']for r in roots})==32
 # Exact and millimetre-quantized block layouts must differ from historical saved configurations.
 def near(a,b):return all(np.allclose(a[c]['initial_pos'],b[c]['initial_pos'],atol=.001,rtol=0)and np.allclose(a[c]['initial_orn'],b[c]['initial_orn'],atol=.001,rtol=0)for c in a)
 assert not[(r['root_id'],o['path'])for r in roots for o in old if near(r['blocks'],o['layout']['blocks'])]
 protocol={'utc':now(),'task':'Bounded RGB-only synchronous visible-box localization baseline; not world-model or closed-loop completion','budget':{'roots':32,'states_per_root':8,'primary_images':512,'primary_states':256,'integrity_duplicate_renders':512,'new_model_downloads':0,'fits':2,'updates_per_fit':1200},'split':{'train':'A/B: 16 fresh roots, 128 states, 256 images','dev':'C: 8 fresh roots, 64 states, 128 images','final':'D: 8 fresh roots, 64 states, 128 images','claim':'Root-disjoint fresh initializations in known scene configurations; not unseen scenes or independent within-root frames','old_4state_8images':'technical regression only, excluded from all fitting/scoring'},'roots':roots,'collection':{'state0':'native reset; then seven fixed motor waypoints; no post-reset teleports','waypoint_execution':'native robot.apply_action, eight stepSimulation calls, scene.step; same dynamics sequence as env.step, intermediate renders omitted','success_selection':False,'all_unreached_and_collision_states_retained':True,'technical_failure':'retain all attempts, repair and deterministic retry allowed; preserve experimental conditions and cap unique samples','single_gpu_lock':True},'labels':{'GT_only':'supervision/evaluation; model inputs RGB only','front':'visible exterior front slab and attached handle; exclude cavity-facing inner board, sides, floor','fingers':'unordered mechanical finger-plus-tip families, two objects','depth_agreement_m':.0005,'any_unknown_drawer_pixel':'entire front image-class unknown; no front box loss or scoring','zero_visible_pixels':'unknown visibility/occlusion/out-of-view cause; never object nonexistent; ignore whole image-class if any expected family has zero pixels','unknown_class_gradient':0,'box':'visible xyxy half-open, no amodal inference','negative_supervision':'background patch centers in valid image-classes; report handle patches with no finger pixels/center as confusing hard-negative context','absence_negative_claim':'No certified whole-image absence labels expected; zero masks remain unknown. Presence/absence generalization is not established.'},'gates':{'sync_and_split_integrity':'all planned samples and roots, flag-off RGB/depth equality, identical pre/post full snapshot, no shared root or identical full dual-camera pair across splits','minimum_valid_positive_boxes_per_class_camera':{'train':32,'dev':12,'final':12},'minimum_positive_roots_per_class_camera':{'train':6,'dev':4,'final':4},'minimum_handle_hardnegative_images_per_camera':{'train':16,'dev':8,'final':8},'minimum_handle_hardnegative_roots_per_camera':{'train':6,'dev':4,'final':4},'unknown_fraction':'reported without relaxing labels; no extra fraction cutoff beyond actual positive/root coverage','failure_action':'data gate report; no fitting, no automatic data expansion'},'model':{'backbone':'cached frozen DINOv2-small','resolution':448,'grid':32,'head':'shared Linear384->64, SiLU, Linear64->15 (3 slots x [logit,dx,dy,w,h]); one front slot and two exchangeable finger slots','finger_slot_assignment':'at each positive center patch sort GT by center x then y, assign slot1 then slot2; identical class, no inference ordering','center':'.5*tanh offsets within patch','size':'sigmoid normalized width,height','input':'RGB bilinear 448 resize; ImageNet mean/std; DINO patch feature channel mean/std from train only (std floor .05)','loss':'valid image-class focal(alpha .25,gamma2), normalized per-image positive count; +5 smoothL1 +2 GIoU for positive boxes','decoder':'all patch/slot candidates score>=.5, classwise greedy NMS IoU>.5; no local-peak suppression, no cardinality cap','metrics':'greedy score-ordered one-to-one IoU>=.5 matching, TP FP FN precision recall F1 matched-TP mean IoU; unknown image-classes excluded; per class/camera/split and per root','no_augmentation':True},'training':{'seeds':[0,1],'updates':1200,'batch_size':16,'optimizer':'AdamW','learning_rate':.001,'weight_decay':.0001,'gradient_clip':1.,'checkpoint':'final only','development_use':'report only after both final checkpoints frozen; no selection or tuning','final_holdout':'predict once per seed after checkpoints frozen; predictions saved and hashed before opening final labels; one scoring invocation','no_search':True},'visual_selection':'predefined root indices 0 and 7 and state indices 0 and 4 per split/camera; not selected by score; display GT unknown explicitly'}
 save(E/'configs/protocol.json',protocol);save(E/'configs/historical_initialization_exclusion.json',{'checked_saved_configs':len(old),'historical_configs':old,'new_signature_unique':True,'within_1mm_reuse':False,'does_not_claim_unseen_assets_or_all_possible_historical_states':True})
 source=P/'experiments/endpoint_sync_truth_4state_retry_20261018/configs/mesh_semantics.json';shutil.copy2(source,E/'configs/mesh_semantics.json')
 for f in Path(__file__).parent.glob('*.py'):shutil.copy2(f,E/'source'/f.name)
 save(E/'configs/precollection_frozen.json',{'utc':now(),'before_first_new_render':True,'sha256':{str(f):sha(f)for sub in ['configs','source']for f in (E/sub).rglob('*')if f.is_file()}})
 print('PROTOCOL_FROZEN',E,sha(E/'configs/precollection_frozen.json'),flush=True)
if __name__=='__main__':main()
